mapper.select:
SELECT COUNT(1)
  FROM tb_bbs_category
 WHERE bbs_master_id = #{bbsMasterId}
   AND category_code = #{categoryCode}
   AND delete_yn     = 'N'

   AND category_id  <> #{excludeCategoryId}

mapper.delete:
DELETE FROM tb_bbs_category
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}

mapper.select:
SELECT COUNT(*) FROM tb_bbs_category
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
